/* ============================================
   LIGHTBOX COMPONENT
   Fullscreen media viewer over a frosted scrim
   ============================================ */

.ds-lightbox {
  position: fixed;
  inset: 0;
  z-index: 100;
  opacity: 0;
  visibility: hidden; /* keeps panel controls out of the tab order when closed */
  pointer-events: none;
  transition:
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-lightbox--open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

/* ============================================
   BACKDROP
   The scrim, frosted: blurring the page behind
   separates the media without a deeper token
   ============================================ */

.ds-lightbox__backdrop {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
  /* The frost's strength; an effect length with no token family, chosen by
     eye — enough to dissolve page detail behind a full-viewport image. */
  --ds-lightbox-frost: 12px;
  backdrop-filter: blur(var(--ds-lightbox-frost));
}

/* A media viewer wants a deeper floor than the dialogs' scrim: the same
   token laid twice compounds it (≈0.75 light / ≈0.91 dark) while staying
   theme-driven — no literal colour, no second scrim role. */
.ds-lightbox__backdrop::after {
  content: '';
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
}

/* ============================================
   PANEL
   A full-viewport stage: transparent to clicks
   so the backdrop hears them, while the media
   and controls stay interactive
   ============================================ */

.ds-lightbox__panel {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--padding-1000);
  pointer-events: none;
  outline: none;
}

.ds-lightbox__panel > * {
  pointer-events: auto;
}

/* ============================================
   MEDIA
   ============================================ */

.ds-lightbox__figure {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--gap-400);
  margin: 0;
  max-width: 100%;
  max-height: 100%;
  transform: scale(0.96);
  transition: transform var(--motion-duration-base) var(--motion-ease-entrance);
}

.ds-lightbox--open .ds-lightbox__figure {
  transform: scale(1);
}

.ds-lightbox__img {
  display: block;
  max-width: calc(100vw - var(--gap-1000) * 4);
  max-height: calc(100vh - var(--gap-1000) * 4);
  width: auto;
  height: auto;
  border-radius: var(--radius-300);
  box-shadow: var(--shadow-modal);
}

/* Custom media (children) takes the same viewport bounds. */
.ds-lightbox__figure > :not(figcaption) {
  max-width: calc(100vw - var(--gap-1000) * 4);
  max-height: calc(100vh - var(--gap-1000) * 4);
}

/* ============================================
   CAPTION
   A glass chip under the media — legible over
   the scrim in both themes
   ============================================ */

.ds-lightbox__caption {
  padding: var(--padding-100) var(--padding-400);
  border-radius: var(--radius-pill);
  /* ds-allow(color): on-scrim furniture — the scrim floor is dark in both
     themes, so the caption chip lives in scrim-world, not page-world; a
     theme token would dissolve it into the dark-mode scrim. */
  background-color: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(var(--ds-lightbox-frost, 12px));
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  /* ds-allow(color): white text on the always-dark scrim wash, both themes */
  color: #ffffff;
  text-align: center;
  max-width: calc(100vw - var(--gap-1000) * 4);
}

/* ============================================
   CONTROLS
   Glass icon buttons: close pinned to the
   viewer's corner, chevrons at its edges
   ============================================ */

.ds-lightbox__control {
  position: absolute;
  z-index: 1; /* above the media — DOM order alone would sink the prev chevron under a full-width image */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--icon-size-1200); /* 48px — a viewer-scale target */
  height: var(--icon-size-1200);
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  /* ds-allow(color): on-scrim furniture — the scrim floor is dark in both
     themes, so the control wash lives in scrim-world, not page-world; a
     theme token would dissolve the controls into the dark-mode scrim. */
  background-color: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(var(--ds-lightbox-frost, 12px));
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-lightbox__control:hover {
  /* ds-allow(color): the same on-scrim wash, one step brighter on hover */
  background-color: rgba(255, 255, 255, 0.24);
}

.ds-lightbox__control:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-lightbox__control-icon {
  --icon-size: var(--icon-size-600);
  line-height: 1;
  /* ds-allow(color): white glyph on the always-dark scrim wash, both themes */
  color: #ffffff;
}

.ds-lightbox__close {
  top: var(--gap-500);
  right: var(--gap-500);
}

.ds-lightbox__nav {
  top: 50%;
  transform: translateY(-50%);
}

.ds-lightbox__nav--prev {
  left: var(--gap-500);
}

.ds-lightbox__nav--next {
  right: var(--gap-500);
}

/* ============================================
   RESPONSIVE
   Tighter margins on small screens — the
   chevrons overlay the media's edges
   ============================================ */

@media (max-width: 480px) {
  .ds-lightbox__panel {
    padding: var(--padding-400);
  }

  .ds-lightbox__img,
  .ds-lightbox__figure > :not(figcaption),
  .ds-lightbox__caption {
    max-width: calc(100vw - var(--gap-400) * 2);
  }
}

'use client';

import React, { useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import './Lightbox.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

/** Props owned by Lightbox itself — everything else falls through to the panel. */
type LightboxOwnProps = {
  /** Whether the lightbox is open */
  open: boolean;
  /** Callback when the lightbox requests to close */
  onOpenChange: (open: boolean) => void;
  /** The image to show. Omit it when `children` supplies the media. */
  src?: string;
  /** Image alt text — also the panel's accessible name. Required whenever `src` is set. */
  alt?: string;
  /** Optional caption shown in a chip under the media */
  caption?: string;
  /**
   * Custom media instead of `src` — a framework image component, a video, a
   * live embed. Sized by the same viewport bounds the plain image gets.
   */
  children?: React.ReactNode;
  /** Whether ESC, backdrop click, and the close button can dismiss */
  dismissible?: boolean;
  /**
   * Steps to the previous item. Providing it renders the previous chevron and
   * arms the Left arrow key — the consumer owns the collection and the index.
   */
  onPrev?: () => void;
  /** Steps to the next item — the next chevron and the Right arrow key. */
  onNext?: () => void;
  /** Additional CSS classes — applied to the portal container, not the panel */
  className?: string;
};

export interface LightboxProps
  extends LightboxOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof LightboxOwnProps> {}

/**
 * Lightbox — the fullscreen media viewer: an image (or custom media) centred
 * over a deep frosted scrim, with a caption chip, a close control, and
 * optional previous/next stepping for galleries. Rides the shared overlay
 * behavior layer: Escape routes through the layer stack, focus is trapped
 * and restored with the page inert behind the panel, and the body scroll
 * lock is counted.
 *
 * Renders through a portal into `document.body`. The forwarded ref and any
 * unrecognised props target the **panel** (the `role="dialog"` element).
 */
export const Lightbox = React.forwardRef<HTMLDivElement, LightboxProps>(
  (
    {
      open,
      onOpenChange,
      src,
      alt,
      caption,
      children,
      dismissible = true,
      onPrev,
      onNext,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const panelRef = useRef<HTMLDivElement | null>(null);
    const baseClass = 'ds-lightbox';

    /** Keep the internal ref (used by the focus trap) while honouring a forwarded one. */
    const setPanelRef = (node: HTMLDivElement | null) => {
      panelRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // SSR guard — only render portal on the client
    const mounted = useMounted();

    // Shared overlay behaviors (src/behaviors/): Escape routes through the
    // layer stack, focus is trapped with the page inert behind the panel,
    // and the scroll lock is counted. Backdrop dismissal stays below — it
    // is this component's own DOM.
    useLayer({ open, dismissOnEscape: dismissible, onDismiss: () => onOpenChange(false) });
    useFocusScope(panelRef, { active: open });
    useScrollLock(open);

    // Gallery stepping is this component's own listener, gated on open state
    // like the non-modal overlays' — the layer stack owns dismissal keys
    // only. Handlers ride refs so the subscription doesn't churn per render.
    const stepRef = useRef({ onPrev, onNext });
    stepRef.current = { onPrev, onNext };
    useEffect(() => {
      if (!open || (!onPrev && !onNext)) return;
      const onKey = (e: KeyboardEvent) => {
        if (e.key === 'ArrowLeft') stepRef.current.onPrev?.();
        if (e.key === 'ArrowRight') stepRef.current.onNext?.();
      };
      document.addEventListener('keydown', onKey);
      return () => document.removeEventListener('keydown', onKey);
    }, [open, onPrev, onNext]);

    const handleBackdropClick = () => {
      if (dismissible) onOpenChange(false);
    };

    const containerClasses = [baseClass, open ? `${baseClass}--open` : '', className]
      .filter(Boolean)
      .join(' ');

    const lightbox = (
      <div className={containerClasses}>
        <div className={`${baseClass}__backdrop`} onClick={handleBackdropClick} />

        <div
          {...rest}
          ref={setPanelRef}
          className={`${baseClass}__panel`}
          role="dialog"
          aria-modal="true"
          aria-label={alt || caption || 'Media viewer'}
          tabIndex={-1}
        >
          {dismissible && (
            <button
              type="button"
              className={`${baseClass}__control ${baseClass}__close`}
              onClick={() => onOpenChange(false)}
              aria-label="Close viewer"
            >
              <span className={`${baseClass}__control-icon material-symbols-rounded`} aria-hidden="true">
                close
              </span>
            </button>
          )}

          {onPrev && (
            <button
              type="button"
              className={`${baseClass}__control ${baseClass}__nav ${baseClass}__nav--prev`}
              onClick={onPrev}
              aria-label="Previous"
            >
              <span className={`${baseClass}__control-icon material-symbols-rounded`} aria-hidden="true">
                chevron_left
              </span>
            </button>
          )}

          <figure className={`${baseClass}__figure`}>
            {children ?? (src ? <img className={`${baseClass}__img`} src={src} alt={alt ?? ''} /> : null)}
            {caption && <figcaption className={`${baseClass}__caption`}>{caption}</figcaption>}
          </figure>

          {onNext && (
            <button
              type="button"
              className={`${baseClass}__control ${baseClass}__nav ${baseClass}__nav--next`}
              onClick={onNext}
              aria-label="Next"
            >
              <span className={`${baseClass}__control-icon material-symbols-rounded`} aria-hidden="true">
                chevron_right
              </span>
            </button>
          )}
        </div>
      </div>
    );

    if (!mounted) return null;
    return ReactDOM.createPortal(lightbox, document.body);
  },
);

Lightbox.displayName = 'Lightbox';
